function buildOrder(array $dependencies): ?array {
    $degree = []; $next = [];
    foreach ($dependencies as $module => $deps) {
        $degree[$module] ??= 0;
        foreach (array_unique($deps, SORT_STRING) as $dep) {
            $degree[$dep] ??= 0;
            $next[$dep][] = $module;
            $degree[$module]++;
        }
    }
    $queue = new SplQueue();
    foreach ($degree as $node => $n) if ($n === 0) $queue->enqueue($node);
    $order = [];
    while (!$queue->isEmpty()) {
        $node = $queue->dequeue(); $order[] = $node;
        foreach ($next[$node] ?? [] as $dependent) {
            if (--$degree[$dependent] === 0) $queue->enqueue($dependent);
        }
    }
    return count($order) === count($degree) ? $order : null;
}

